import{_ as a,y as i,a as l,o as g,a2 as r,g as t,D as n,I as s}from"./chunks/framework.DCcmcJcL.js";const R=JSON.parse('{"title":"Return Merchandise Authorization (RMA)","description":"","frontmatter":{},"headers":[],"relativePath":"orders/rma.md","filePath":"orders/rma.md","lastUpdated":1789441803000}'),u={name:"orders/rma.md"};function d(h,e,c,m,p,q){const o=i("ImagePopup");return g(),l("div",null,[e[12]||(e[12]=r('<h1 id="return-merchandise-authorization-rma" tabindex="-1">Return Merchandise Authorization (RMA) <a class="header-anchor" href="#return-merchandise-authorization-rma" aria-label="Permalink to &quot;Return Merchandise Authorization (RMA)&quot;">​</a></h1><p>RMA lets customers ask to return or cancel an item from an order, and lets you approve the request, refund or cancel the item, and message the customer, all in one place. Each request covers one item and moves through statuses such as <strong>Pending Review</strong>, <strong>Approved</strong> and <strong>Refunded</strong>.</p><p>The return window, return policy, attachments and reopening are set in <a href="./../configure/rma.html">RMA settings</a>.</p><h2 id="how-a-return-works" tabindex="-1">How a return works <a class="header-anchor" href="#how-a-return-works" aria-label="Permalink to &quot;How a return works&quot;">​</a></h2><ol><li>You allow returns on your products and give them a return period.</li><li>A customer requests a return or cancellation for an item, or you create the request for them. It starts as <strong>Pending Review</strong>.</li><li>You approve or decline the request.</li><li>While the item comes back, you move the request to <strong>Awaiting Return</strong> and <strong>Return In Transit</strong>.</li><li>You refund or cancel the item from the request. The request closes as <strong>Refunded</strong> or <strong>Item Canceled</strong>.</li></ol><p>The customer can also cancel the request, or mark it as solved.</p><h2 id="allow-returns-on-a-product" tabindex="-1">Allow returns on a product <a class="header-anchor" href="#allow-returns-on-a-product" aria-label="Permalink to &quot;Allow returns on a product&quot;">​</a></h2><p>A product can be returned only when <strong>Allow RMA</strong> is on for it.</p><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Open the product.</li><li>In <strong>RMA</strong>, switch on <strong>Allow RMA</strong>.</li><li>Choose a rule in <strong>RMA Rules</strong>.</li><li>Click <strong>Save Product</strong>.</li></ol><ul><li>The <strong>RMA</strong> section shows on simple products, on variants, and on the product types chosen in <strong>Allow Product Type For RMA</strong> in <a href="./../configure/rma.html">RMA settings</a>. Returns are allowed only if the product&#39;s type is chosen there when the order is placed. Virtual, downloadable and booking products don&#39;t have the section.</li><li>For a grouped product, set <strong>Allow RMA</strong> on its simple products. For a configurable product, set it on the main product.</li><li>The return period comes from the product&#39;s rule, if the rule is active. Otherwise <strong>Default allowed days</strong> from the settings is used.</li><li>The return period is saved on the order when it&#39;s placed, and is counted from the order date. Changing a rule or a setting later doesn&#39;t change orders already placed.</li><li>The period applies to both returns and cancellations.</li></ul><h2 id="reasons" tabindex="-1">Reasons <a class="header-anchor" href="#reasons" aria-label="Permalink to &quot;Reasons&quot;">​</a></h2><p>Reasons are the choices customers pick from when they make a request. Bagisto comes with five: <strong>Manufacturer Defect</strong>, <strong>Damaged During Shipping</strong>, <strong>Wrong Description Online</strong>, <strong>Dead On Arrival</strong> and <strong>Product Not Received Yet</strong>.</p><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Reasons</strong> to see each reason with its <strong>ID</strong>, <strong>Reason</strong>, <strong>Status</strong>, <strong>Resolution Type</strong>, <strong>Position</strong> and <strong>Created At</strong>.</p><h3 id="create-a-reason" tabindex="-1">Create a reason <a class="header-anchor" href="#create-a-reason" aria-label="Permalink to &quot;Create a reason&quot;">​</a></h3>',14)),t("ol",null,[e[1]||(e[1]=r("<li><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Reasons</strong>.</p></li><li><p>Click <strong>Create RMA Reason</strong>. The <strong>Add New Reason</strong> form opens.</p></li><li><p>Enter the <strong>Reason</strong>, such as &quot;Wrong size delivered&quot;.</p></li><li><p>Switch <strong>Status</strong> on. A new reason starts switched off, and only active reasons are offered.</p></li><li><p>Enter the <strong>Position</strong>, a number of 1 or more.</p></li>",5)),t("li",null,[e[0]||(e[0]=t("p",null,[s("In "),t("strong",null,"Resolution Type"),s(", choose "),t("strong",null,"Return/Refund"),s(", "),t("strong",null,"Cancel-items"),s(" or both. The reason is offered for the types you choose.")],-1)),n(o,{src:"/images/orders/rma-reason.png",alt:"Add New Reason form with the reason, status, position and resolution type"})]),e[2]||(e[2]=t("li",null,[t("p",null,[s("Click "),t("strong",null,"Save Reason"),s(".")])],-1))]),e[13]||(e[13]=r('<p>To change a reason, click its edit icon. To switch several reasons on or off, select them and use <strong>Update</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p>A rule sets how many days customers have to request a return or cancellation for the products it&#39;s assigned to. Bagisto comes with the rule <strong>Basic</strong>, with 10 days.</p><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Rules</strong> to see each rule with its <strong>ID</strong>, <strong>Name</strong>, <strong>Status</strong> and <strong>Return Period (Days)</strong>.</p><h3 id="create-a-rule" tabindex="-1">Create a rule <a class="header-anchor" href="#create-a-rule" aria-label="Permalink to &quot;Create a rule&quot;">​</a></h3>',5)),t("ol",null,[e[4]||(e[4]=r("<li><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Rules</strong>.</p></li><li><p>Click <strong>Create RMA Rules</strong>. The <strong>Add New RMA Rules</strong> form opens.</p></li><li><p>Enter the <strong>Rules Title</strong>.</p></li><li><p>Switch <strong>Status</strong> on. Only active rules can be chosen on a product.</p></li><li><p>Enter the <strong>Rules Description</strong>, which is required, up to 70 characters.</p></li>",5)),t("li",null,[e[3]||(e[3]=t("p",null,[s("Enter the "),t("strong",null,"Return Period (Days)"),s(", 1 or more. If you leave it empty, "),t("strong",null,"Default allowed days"),s(" is used.")],-1)),n(o,{src:"/images/orders/rma-rules.png",alt:"Add New RMA Rules form with the title, description and return period"})]),e[5]||(e[5]=t("li",null,[t("p",null,[s("Click "),t("strong",null,"Save RMA Rules"),s(".")])],-1))]),e[14]||(e[14]=r('<p>Then <a href="#allow-returns-on-a-product">assign the rule to products</a>. If you delete a rule, new orders for its products use <strong>Default allowed days</strong> instead.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><p>A request&#39;s status shows where it stands. Bagisto comes with nine statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th><th>How it&#39;s set</th></tr></thead><tbody><tr><td><strong>Pending Review</strong></td><td>A new or reopened request waiting for your review.</td><td>When a request is created or reopened.</td></tr><tr><td><strong>Approved</strong></td><td>You accepted the request.</td><td>You choose it.</td></tr><tr><td><strong>Awaiting Return</strong></td><td>You&#39;re waiting for the customer to send the item back.</td><td>You choose it.</td></tr><tr><td><strong>Return In Transit</strong></td><td>The item is on its way back. Return requests only.</td><td>You choose it.</td></tr><tr><td><strong>Refunded</strong></td><td>The item has been refunded.</td><td><strong>Refund Item</strong> on the request.</td></tr><tr><td><strong>Solved</strong></td><td>The customer marked the request as solved.</td><td>The customer, on the storefront.</td></tr><tr><td><strong>Request Declined</strong></td><td>You declined the request.</td><td>You choose it, while the request is <strong>Pending Review</strong>.</td></tr><tr><td><strong>Item Canceled</strong></td><td>The item has been canceled on the order.</td><td><strong>Cancel Item</strong> on the request.</td></tr><tr><td><strong>Request Canceled</strong></td><td>The request was canceled.</td><td>The customer, or you once the request is past <strong>Pending Review</strong>.</td></tr></tbody></table><p><strong>Refunded</strong>, <strong>Solved</strong>, <strong>Request Declined</strong>, <strong>Item Canceled</strong> and <strong>Request Canceled</strong> close the request. A declined or canceled request can be <a href="#reopen-a-request">reopened</a> when the settings allow it.</p><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Statuses</strong> to see each status with its <strong>ID</strong>, <strong>Title</strong>, <strong>Color</strong> and <strong>Status</strong>.</p><h3 id="create-a-status" tabindex="-1">Create a status <a class="header-anchor" href="#create-a-status" aria-label="Permalink to &quot;Create a status&quot;">​</a></h3><p>Add your own statuses for steps in your process, such as &quot;Replacement Shipped&quot;.</p>',8)),t("ol",null,[e[7]||(e[7]=r("<li><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Statuses</strong>.</p></li><li><p>Click <strong>Create RMA Status</strong>. The <strong>Add New RMA Status</strong> form opens.</p></li><li><p>Enter the <strong>Title</strong>. It must be different from every other status.</p></li><li><p>Switch <strong>Status</strong> on.</p></li>",4)),t("li",null,[e[6]||(e[6]=t("p",null,[s("Choose the "),t("strong",null,"Color"),s(" used for the status in the lists and on the request.")],-1)),n(o,{src:"/images/orders/rma-status.png",alt:"Add New RMA Status form with the title, status and color"})]),e[8]||(e[8]=t("li",null,[t("p",null,[s("Click "),t("strong",null,"Save RMA Status"),s(".")])],-1))]),e[15]||(e[15]=r('<ul><li>Active statuses you create are offered in <strong>Change Request Status</strong> once a request is past <strong>Pending Review</strong>. Choosing one doesn&#39;t change the order, but the customer is emailed and <strong>Order Actions</strong> are hidden. To refund or cancel the item later, move the request back to <strong>Awaiting Return</strong> or <strong>Return In Transit</strong>.</li><li>For the nine default statuses, the edit form changes only the <strong>Color</strong>, and saving it switches the status on. Default statuses can&#39;t be deleted. Keep them switched on, because the request workflow depends on them.</li></ul><h2 id="custom-fields" tabindex="-1">Custom fields <a class="header-anchor" href="#custom-fields" aria-label="Permalink to &quot;Custom fields&quot;">​</a></h2><p>Custom fields ask customers for extra details when they make a request, such as their preferred replacement size.</p><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Custom Fields</strong> to see each field with its <strong>ID</strong>, <strong>Code</strong>, <strong>Label</strong>, <strong>Type</strong>, <strong>Required</strong> and <strong>Status</strong>.</p><h3 id="add-a-custom-field" tabindex="-1">Add a custom field <a class="header-anchor" href="#add-a-custom-field" aria-label="Permalink to &quot;Add a custom field&quot;">​</a></h3>',5)),t("ol",null,[e[10]||(e[10]=r("<li><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Custom Fields</strong>.</p></li><li><p>Click <strong>Add New Field</strong>. The <strong>New Custom Field</strong> page opens.</p></li><li><p>Switch <strong>Status</strong> on. A new field starts switched off.</p></li><li><p>Enter the <strong>Label</strong> customers see.</p></li><li><p>Enter a <strong>Code</strong>, which must be unique.</p></li><li><p>Enter the <strong>Position</strong>.</p></li><li><p>Choose the <strong>Type</strong>: <strong>Text</strong>, <strong>Textarea</strong>, <strong>Date</strong>, <strong>Select</strong>, <strong>Multiselect</strong>, <strong>Checkbox</strong> or <strong>Radio</strong>.</p></li><li><p>For <strong>Select</strong>, <strong>Multiselect</strong>, <strong>Checkbox</strong> or <strong>Radio</strong>, enter the first choice in <strong>Options</strong> and <strong>Value</strong>.</p></li><li><p>Click <strong>Add Option</strong> for each further choice.</p></li>",9)),t("li",null,[e[9]||(e[9]=t("p",null,[s("To make customers fill in the field, tick "),t("strong",null,"Is Required"),s(".")],-1)),n(o,{src:"/images/orders/rma-custom.png",alt:"New Custom Field page with the label, code, position and type"})]),e[11]||(e[11]=t("li",null,[t("p",null,[s("Click "),t("strong",null,"Save"),s(".")])],-1))]),e[16]||(e[16]=r('<p>Active fields appear on the request form for customers and admins, and the answers are shown on the request. The storefront form won&#39;t submit without a required field; in the admin form, a required <strong>Checkbox</strong> field isn&#39;t enforced. For a <strong>Text</strong> field, <strong>Input Validation</strong> offers <strong>Number</strong>, <strong>Email</strong>, <strong>Decimal</strong> and <strong>URL</strong>, and a new field is saved with <strong>Number</strong>. Bagisto doesn&#39;t check answers against it, so say in the <strong>Label</strong> what format you need.</p><h3 id="before-you-delete-a-reason-status-or-field" tabindex="-1">Before you delete a reason, status or field <a class="header-anchor" href="#before-you-delete-a-reason-status-or-field" aria-label="Permalink to &quot;Before you delete a reason, status or field&quot;">​</a></h3><p>Switch a reason, status or custom field off rather than deleting it once requests have used it. Don&#39;t delete custom statuses; switch them off instead. Requests that used a deleted reason or status can no longer be opened, and deleting a custom field removes the answers stored on past requests.</p><h2 id="handle-return-requests" tabindex="-1">Handle return requests <a class="header-anchor" href="#handle-return-requests" aria-label="Permalink to &quot;Handle return requests&quot;">​</a></h2><h3 id="the-requests-screen" tabindex="-1">The Requests screen <a class="header-anchor" href="#the-requests-screen" aria-label="Permalink to &quot;The Requests screen&quot;">​</a></h3><p>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong> to see every request with its <strong>RMA ID</strong>, <strong>Order Ref</strong>, <strong>Customer Name</strong>, <strong>Request Status</strong> and <strong>Created At</strong>. A guest order shows <strong>(Guest)</strong> after the name. Click <strong>View</strong> to open a request.</p>',6)),n(o,{src:"/images/orders/rma-all-request.png",alt:"Requests screen listing return requests with their status"}),e[17]||(e[17]=r('<h3 id="create-a-request-for-a-customer" tabindex="-1">Create a request for a customer <a class="header-anchor" href="#create-a-request-for-a-customer" aria-label="Permalink to &quot;Create a request for a customer&quot;">​</a></h3><p>You can create a request for any customer&#39;s order, including guest orders.</p><ol><li>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong>.</li><li>Click <strong>Create</strong>. The <strong>Create RMA</strong> page lists the orders that can have a request.</li><li>Click the edit icon in the order&#39;s <strong>Action</strong> column. The <strong>Create RMA</strong> form opens.</li><li>Tick the item. A request covers one item.</li><li>Choose the <strong>Resolution Type</strong>: <strong>Return/Refund</strong> or <strong>Cancel-items</strong>.</li><li>Choose the <strong>Reason</strong>.</li><li>Enter the <strong>Quantity</strong>.</li><li>For a return, choose the <strong>Package Condition</strong>, <strong>Open</strong> or <strong>Packed</strong>, if you know it.</li><li>Fill in the custom fields.</li><li>Enter any <strong>Additional Information</strong>, up to 250 characters.</li><li>Add <strong>Images</strong>, if the customer sent any.</li><li>Click <strong>Save</strong>.</li></ol><p>The request opens with the status <strong>Pending Review</strong>.</p><ul><li>An order is listed when it isn&#39;t <strong>Canceled</strong>, <strong>Closed</strong>, <strong>Fraud</strong> or <strong>Pending Payment</strong>, and it has an item within its return period with a quantity that isn&#39;t already in a request.</li><li>An order can still be listed after its items were refunded or canceled on the order; the form then says <strong>Item not available for RMA</strong>.</li><li><strong>Return/Refund</strong> is offered when part of the item is invoiced and not refunded, up to that quantity.</li><li><strong>Cancel-items</strong> is offered when part of the item isn&#39;t invoiced or canceled, up to that quantity.</li><li>In the admin panel, the quantity limit doesn&#39;t subtract quantity already in other requests, so check the item&#39;s requests first.</li></ul><h3 id="the-request-page" tabindex="-1">The request page <a class="header-anchor" href="#the-request-page" aria-label="Permalink to &quot;The request page&quot;">​</a></h3><p>The title shows the request number, such as <strong>RMA ID #4</strong>.</p>',7)),n(o,{src:"/images/orders/rma-request-view.png",alt:"Request page with the request details, item, conversation and status"}),e[18]||(e[18]=r('<ul><li><strong>RMA</strong>: the date of the request, the <strong>Package Condition</strong>, the custom field answers, the <strong>Additional Information</strong> and the images.</li><li><strong>Item Requested for RMA</strong>: the item with its price, quantity, <strong>Resolution Type</strong> and <strong>Reason</strong>, and the <strong>Order Actions</strong> described below.</li><li><strong>Conversations</strong>: the messages between you and the customer.</li><li><strong>Status</strong>: the current status. A <strong>Request Declined</strong> or <strong>Item Canceled</strong> request also says <strong>RMA is closed</strong>.</li><li><strong>Change Request Status</strong> and <strong>Reopen Request</strong>, when they apply.</li><li>A second panel, also headed <strong>Item Requested for RMA</strong>, shows the order&#39;s ID, total, date and payment method, and <strong>Customer Details</strong> shows the customer&#39;s name and email.</li></ul><h3 id="approve-or-decline-a-request" tabindex="-1">Approve or decline a request <a class="header-anchor" href="#approve-or-decline-a-request" aria-label="Permalink to &quot;Approve or decline a request&quot;">​</a></h3><ol><li>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong>.</li><li>Open the request.</li><li>In <strong>Change Request Status</strong>, choose <strong>Approved</strong> or <strong>Request Declined</strong>.</li><li>Click <strong>Save</strong>.</li><li>Click <strong>Agree</strong>.</li></ol><p>The customer is emailed the new status. After approval, <strong>Change Request Status</strong> offers <strong>Awaiting Return</strong>, <strong>Return In Transit</strong> for returns, <strong>Request Canceled</strong> and your own active statuses. Change them the same way. Once a request is closed, <strong>Change Request Status</strong> is hidden.</p><h3 id="refund-the-item" tabindex="-1">Refund the item <a class="header-anchor" href="#refund-the-item" aria-label="Permalink to &quot;Refund the item&quot;">​</a></h3><p><strong>Order Actions</strong> appear while a request is <strong>Approved</strong>, <strong>Awaiting Return</strong> or <strong>Return In Transit</strong>. These actions change the order and can&#39;t be undone.</p><ol><li>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong>.</li><li>Open the request.</li><li>In <strong>Order Actions</strong>, click <strong>Refund Item</strong>. The <strong>Refund Item</strong> form opens.</li><li>Check the <strong>Refund Shipping</strong> amount. It starts at the shipping that can still be refunded.</li><li>Click <strong>Refund Item</strong>.</li></ol><p>The refund is created as soon as you click: a refund for the request&#39;s quantity plus the shipping amount, with no adjustment refund or fee. The item&#39;s refunded quantity and the order&#39;s totals and status are updated, the request becomes <strong>Refunded</strong>, and the customer is emailed. The refund is listed on the order, as described in <a href="./create-refunds.html">Create Refund</a>.</p><h3 id="cancel-the-item" tabindex="-1">Cancel the item <a class="header-anchor" href="#cancel-the-item" aria-label="Permalink to &quot;Cancel the item&quot;">​</a></h3><p>For a <strong>Cancel-items</strong> request, <strong>Order Actions</strong> shows <strong>Cancel Item</strong>.</p><ol><li>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong>.</li><li>Open the request.</li><li>In <strong>Order Actions</strong>, click <strong>Cancel Item</strong>.</li><li>Click <strong>Agree</strong>.</li></ol><p>The item&#39;s quantity is canceled on the order and the order&#39;s status is updated. The request becomes <strong>Item Canceled</strong>, and the customer is emailed.</p><h3 id="send-a-message" tabindex="-1">Send a message <a class="header-anchor" href="#send-a-message" aria-label="Permalink to &quot;Send a message&quot;">​</a></h3><ol><li>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong>.</li><li>Open the request.</li><li>In <strong>Conversations</strong>, type your message in <strong>Send Message</strong>. A message is required, even when you attach a file.</li><li>To attach a file, click <strong>Add Attachments</strong> and choose the file.</li><li>Click <strong>Send Message</strong>.</li></ol>',14)),n(o,{src:"/images/orders/rma-admin-com.png",alt:"Conversations with messages between the admin and the customer"}),e[19]||(e[19]=r('<p>The customer is emailed the message. Messages load five at a time; scroll in the list to see older ones. Click an attachment to open it. Images such as JPG and PNG, PDF files and MP4 videos preview in a window; other files, such as WEBP images, show only <strong>Download</strong>. The file types allowed are set in <strong>Allowed File Extension</strong> in <a href="./../configure/rma.html">RMA settings</a>.</p><h3 id="reopen-a-request" tabindex="-1">Reopen a request <a class="header-anchor" href="#reopen-a-request" aria-label="Permalink to &quot;Reopen a request&quot;">​</a></h3><p><strong>Reopen Request</strong> appears on a declined request when <strong>Allow Reopening Declined Returns</strong> is <strong>Yes</strong>, and on a canceled request when <strong>Allow Reopening Cancelled Returns</strong> is <strong>Yes</strong>.</p><ol><li>Go to <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong>.</li><li>Open the request.</li><li>In <strong>Reopen Request</strong>, tick <strong>Reopen Request</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>The request goes back to <strong>Pending Review</strong>, and the customer is emailed.</p><h2 id="customers-request-a-return" tabindex="-1">Customers: request a return <a class="header-anchor" href="#customers-request-a-return" aria-label="Permalink to &quot;Customers: request a return&quot;">​</a></h2><p>Customers with an account request returns from their account on the storefront. Guests can&#39;t; create the request for them in the admin panel.</p><h3 id="create-a-request" tabindex="-1">Create a request <a class="header-anchor" href="#create-a-request" aria-label="Permalink to &quot;Create a request&quot;">​</a></h3><ol><li>Sign in to the storefront account and open <strong>RMA</strong>.</li><li>Click <strong>New RMA Request</strong>. The orders that can have a request are listed.</li><li>Click the edit icon in the order&#39;s <strong>Action</strong> column. The <strong>New RMA Request</strong> form opens.</li><li>Tick the item.</li><li>Choose the <strong>Resolution Type</strong>: <strong>Return/Refund</strong> or <strong>Cancel Items</strong>. For a return, the item shows its <strong>Return Window</strong>.</li><li>Choose the <strong>Reason</strong>.</li><li>Enter the <strong>RMA Qty</strong>.</li><li>For a return, choose the <strong>Package Condition</strong>, if wanted.</li><li>Fill in any custom fields.</li><li>Enter any <strong>Additional Information</strong>, up to 250 characters.</li><li>Add <strong>Images</strong>, if wanted.</li><li>Tick <strong>I agree to the Terms and Conditions</strong>. <strong>Read Terms and Conditions</strong> shows the store&#39;s return policy.</li><li>Click <strong>Submit request</strong>.</li></ol><p>The customer sees <strong>Request created successfully.</strong> and the request opens with <strong>Pending Review</strong>. You aren&#39;t emailed about new requests, so check the <strong>Requests</strong> screen regularly.</p><h3 id="the-customer-s-requests" tabindex="-1">The customer&#39;s requests <a class="header-anchor" href="#the-customer-s-requests" aria-label="Permalink to &quot;The customer&#39;s requests&quot;">​</a></h3><p><strong>RMA</strong> in the account lists each request with its <strong>RMA ID</strong>, <strong>Order Reference</strong>, <strong>Request Status</strong>, <strong>Quantity</strong> and <strong>Created At</strong>, with <strong>View</strong> and, while the request is open, <strong>Cancel</strong>.</p>',12)),n(o,{src:"/images/orders/customer-rma.png",alt:"Customer's RMA list on the storefront"}),e[20]||(e[20]=t("p",null,[s("The request page shows "),t("strong",null,"RMA Details"),s(", the "),t("strong",null,"Item Requested for RMA"),s(", and "),t("strong",null,"Conversations"),s(", where the customer can send you a message of up to 250 characters with an attachment. You're emailed each message.")],-1)),n(o,{src:"/images/orders/rma-conversation.png",alt:"Customer's conversation on a return request"}),e[21]||(e[21]=r('<h3 id="cancel-a-request" tabindex="-1">Cancel a request <a class="header-anchor" href="#cancel-a-request" aria-label="Permalink to &quot;Cancel a request&quot;">​</a></h3><ol><li>In the account, open <strong>RMA</strong>.</li><li>Click <strong>Cancel</strong> on the request.</li><li>Click <strong>Agree</strong>.</li></ol>',2)),n(o,{src:"/images/orders/rma-customer-cancel.png",alt:"Cancel action on the customer's RMA list"}),e[22]||(e[22]=r('<p>The request becomes <strong>Request Canceled</strong>.</p><h3 id="mark-a-request-as-solved" tabindex="-1">Mark a request as solved <a class="header-anchor" href="#mark-a-request-as-solved" aria-label="Permalink to &quot;Mark a request as solved&quot;">​</a></h3><ol><li>In the account, open <strong>RMA</strong>.</li><li>Click <strong>View</strong> on the request.</li><li>Tick <strong>Please agree to mark it as solved</strong>.</li><li>Click <strong>Save</strong>.</li></ol>',3)),n(o,{src:"/images/orders/rma-close.png",alt:"Option to mark a return request as solved"}),e[23]||(e[23]=r('<p>The request becomes <strong>Solved</strong> and a note is added to the conversation. The option appears while the request is open, the return window hasn&#39;t passed, and the order isn&#39;t canceled or closed.</p><h3 id="reopen-a-request-1" tabindex="-1">Reopen a request <a class="header-anchor" href="#reopen-a-request-1" aria-label="Permalink to &quot;Reopen a request&quot;">​</a></h3><p>When the settings allow it, a customer can reopen a declined or canceled request within the return window.</p><ol><li>In the account, open <strong>RMA</strong>.</li><li>Click <strong>View</strong> on the request.</li><li>Tick <strong>Reopen Request</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>The request goes back to <strong>Pending Review</strong>.</p><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>When</th><th>Who is emailed</th></tr></thead><tbody><tr><td>A request is created</td><td>The customer.</td></tr><tr><td>You send a message</td><td>The customer.</td></tr><tr><td>The customer sends a message</td><td>The store&#39;s admin email address.</td></tr><tr><td>You change the status, refund or cancel the item, or reopen the request</td><td>The customer, with the new status.</td></tr><tr><td><strong>Refund Item</strong> or <strong>Cancel Item</strong> creates a refund or cancellation</td><td>The customer and the admin also get the usual refund emails, or the usual order-canceled emails, which describe the whole order, when those are on in <a href="./../configure/notifications.html">Notifications</a>.</td></tr></tbody></table><p>No email is sent when a customer cancels, solves or reopens a request. Customers who checked out as guests aren&#39;t emailed about their requests; contact them yourself.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>A role needs <strong>RMA</strong> under <strong>Sales</strong>, with:</p><ul><li><strong>RMA Requests</strong> to see and handle requests, and <strong>Create</strong> to create them. Opening a request from the <strong>Requests</strong> screen also needs <strong>Create</strong>;</li><li><strong>RMA Reasons</strong>, <strong>RMA Rules</strong>, <strong>RMA Statuses</strong> and <strong>Custom Fields</strong>, each with <strong>Create</strong>, <strong>Edit</strong> and <strong>Delete</strong> as needed.</li></ul>',11))])}const w=a(u,[["render",d]]);export{R as __pageData,w as default};
